#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {}
};

class Kitten : public Cat {
public:
    Kitten(string n) : Cat(n) {
        cout << "小猫那一半搭好：" << name << endl;
    }
};

int main() {
    Kitten k("{name}");
    return 0;
}
